begin;
do $$ begin perform set_config('votus_platform_review.admin',pg_has_role(current_user,'workspace_admin_owner','SET')::text,true); if not pg_has_role(current_user,'workspace_admin_owner','SET') then grant workspace_admin_owner to current_user; end if; end $$;
revoke select on table public.review_item,public.review_item_unresolved_count from authenticated,anon;
revoke select(id,kind,severity,subject_ref,detected_at,resolved_at,note,created_at,tenant_scope_state) on public.review_item from authenticated,anon;
revoke select(unresolved_count) on public.review_item_unresolved_count from authenticated,anon;
drop policy review_item_authenticated_read on public.review_item;
grant select on public.review_item to workspace_admin_owner;
create policy workspace_admin_owner_platform_review_select on public.review_item for select to workspace_admin_owner using(resolved_at is null and tenant_scope_state='platform_only');
create index review_item_platform_unresolved_idx on public.review_item(detected_at desc,id) where resolved_at is null and tenant_scope_state='platform_only';
grant create on schema workspace_private to workspace_admin_owner; set role workspace_admin_owner;
create function workspace_private.platform_review_items(p_limit integer default 50,p_offset integer default 0) returns jsonb language plpgsql stable security definer set search_path=pg_catalog,workspace_private,public,pg_temp as $$ declare item_total bigint; items jsonb; category_counts jsonb; reason_counts jsonb; payload jsonb; begin if p_limit is null or p_limit<0 or p_limit>100 or p_offset is null or p_offset<0 or p_offset>2000000000 then raise exception 'invalid platform review pagination' using errcode='22023'; end if; with visible as materialized(select id,kind,severity,detected_at from public.review_item where resolved_at is null and tenant_scope_state='platform_only'),page as(select * from visible order by detected_at desc,id limit p_limit offset p_offset) select (select count(*) from visible),coalesce((select jsonb_agg(jsonb_build_object('id',id,'category',kind,'reason',severity,'detected_at',detected_at) order by detected_at desc,id) from page),'[]'::jsonb),coalesce((select jsonb_agg(jsonb_build_object('category',kind,'count',rows) order by kind) from(select kind,count(*) rows from visible group by kind) grouped),'[]'::jsonb),coalesce((select jsonb_agg(jsonb_build_object('reason',severity,'count',rows) order by severity) from(select severity,count(*) rows from visible group by severity) grouped),'[]'::jsonb) into item_total,items,category_counts,reason_counts; payload:=jsonb_build_object('status',case when jsonb_array_length(items)=0 then 'no_rows' else 'ok' end,'items',items,'category_counts',category_counts,'reason_counts',reason_counts,'total',item_total,'truncated',item_total>p_offset+p_limit,'exclusions',case when item_total>p_offset+p_limit then jsonb_build_array(jsonb_build_object('reason','pagination_bound','rows',item_total-p_offset-p_limit)) else '[]'::jsonb end); if octet_length(payload::text)>8192 then return jsonb_build_object('status','payload_too_large','items','[]'::jsonb,'category_counts',category_counts,'reason_counts',reason_counts,'total',item_total,'truncated',true,'exclusions',jsonb_build_array(jsonb_build_object('reason','payload_bound','rows',jsonb_array_length(items)))); end if; return payload; end $$;
revoke all on function workspace_private.platform_review_items(integer,integer) from public,anon,authenticated; grant execute on function workspace_private.platform_review_items(integer,integer) to workspace_platform_admin;
reset role; revoke create on schema workspace_private from workspace_admin_owner;
do $$ begin if to_regrole('service_role') is not null then revoke all on function workspace_private.platform_review_items(integer,integer) from service_role; end if; if current_setting('votus_platform_review.admin',true)='false' then revoke workspace_admin_owner from current_user; end if; end $$;
commit;
